#!/usr/bin/env python3
"""Freeze selected originals and inference-only input before any LLM/VL call."""
import collections, datetime, hashlib, json, pathlib, subprocess, yaml
P=pathlib.Path('evidence/jit-benchmark-100-20261031')
def sha(b):return hashlib.sha256(b).hexdigest()
def write(n,v): (P/n).write_text(json.dumps(v,ensure_ascii=False,indent=2),encoding='utf-8')
if (P/'freeze-lock.json').exists():raise SystemExit('ALREADY_FROZEN: refusing overwrite')
s=json.loads((P/'selection.json').read_text()); downloads={x['key']:x for x in json.loads((P/'downloads.json').read_text())}; metadata={x['key']:x for x in json.loads((P/'pdf-metadata.json').read_text())}
old=json.loads(pathlib.Path('evidence/jit-quality-20261031/inputs/downloads.json').read_text()); oldsha={d['sha256'] for d in old if d.get('sha256') and d.get('track_id') in s['excluded_regression_documents']}
docs=[];questions=[];sha_splits={}
for d in s['documents']:
    dl=downloads[d['key']]; m=metadata[d['key']]; doc={k:v for k,v in d.items() if k!='questions'};doc.update(download=dl,page_count=m['page_count'])
    if dl['status']=='downloaded':
        if dl['sha256'] in oldsha:raise ValueError('REGRESSION_PDF_DUPLICATE')
        if dl['sha256'] in sha_splits and sha_splits[dl['sha256']]!=d['split']:raise ValueError('CROSS_SPLIT_PDF_DUPLICATE')
        sha_splits[dl['sha256']]=d['split']
    docs.append(doc)
    for q in d['questions']:
        # OHR evidence_page_no is zero based (including 2,449 original page=0).
        # Selected MML anchors match 1-based physical pages. Original indices retained.
        physical=[p+1 for p in q['evidence_pages']] if d['dataset']=='OHR-Bench' else q['evidence_pages'][:]
        questions.append({**q,'document_key':d['key'],'split':d['split'],'physical_evidence_pages':physical,'page_convention':'OHR zero-based +1' if d['dataset']=='OHR-Bench' else 'original physical 1-based','invalid_evidence_pages':[p for p in physical if not 1<=p<=m['page_count']]})
write('frozen-gold.json',dict(documents=docs,questions=questions,regression_count=14,regression_included_in_independent_score=False))
write('inference-manifest.json',dict(documents=[dict(key=d['key'],filename=d['filename'],sha256=d['download']['sha256'],split=d['split']) for d in docs if d['download']['status']=='downloaded'],questions=[{k:q[k] for k in ['id','question','document_key','split','category']} for q in questions]))
config=yaml.safe_load(pathlib.Path('librechat.yaml').read_text());preset=next(x['preset'] for x in config['modelSpecs']['list'] if x['name']=='sansuo-main')
write('production-parameters.json',dict(model=preset['model'],temperature=preset['temperature'],max_tokens=preset['max_tokens'],maxContextTokens=preset['maxContextTokens'],instructions_sha256=sha(preset['instructions'].encode()),recursion_limit=50,mode='deep',thinking='production default; no override',retrieval=dict(candidateDepth=30,queryProcessing=True,rerank=True,compactDelivery=True),query_processor=dict(maxCalls=4,timeoutMs=8000,maxVariants=2),reranker=dict(maxCalls=4,timeoutMs=12000,candidateLimit=20,excerptChars=1200),repository_budget=dict(maxCalls=32,maxContentChars=160000),embedding='text-embedding-v4',concurrency_documents=2,questions_per_document='sequential, fresh conversation, source upload reused via production file references',official_attempts=1,observation_timeout_ms=1800000,question_wrapper='请依据所附文档回答，并引用 PDF 物理页码；无法从文档确认时请明确说明。',no_production_logic_modification=True))
write('license-audit.json',dict(use='Local non-commercial research evaluation only. Do not redistribute PDFs. Underlying source ownership remains with copyright holders.',sources=[dict(dataset='CiteVQA',hf_revision='d80d4f281b849da2f22a1855f4a693357e988ff6',annotations='Official validation JSON previously acquired; SHA bound below',access='Public original PDF URLs from official source CSV, no bypass'),dict(dataset='OHR-Bench',hf_revision='7f833e3eda9a571a9ea545a8f6d476fa1685033d',github_revision='1f421eb428f9f5b8ac0bc8064d6ad1f13fab7af7',annotation_path='data/qas_v2.json',metadata_license='CC-BY-4.0',pdf_restriction='README: research and non-commercial use only',access='Unauthenticated public pdfs.zip, standard HTTP range extraction with CRC verification'),dict(dataset='MMLongBench-Doc',hf_revision='2ff6aa9237fc777b6627dc57a486e9225ac5fb86',github_revision='d73f0dc0be7e0a2ff6a403d5fe65fcd96461f384',annotation_path='data/samples.json',annotation_count=1082,license='Author README data CC-BY-NC-4.0 research only; standalone LICENSE missing',access='Public official HF PDF objects; not gated')]))
write('scoring-protocol.json',dict(inference='One authenticated HTTP production Agent run per original QA. Reference answers/evidence never loaded by inference harness. No retries or tuning on acceptance.',split_counts=dict(collections.Counter(q['split'] for q in questions)),categories=dict(collections.Counter(q['category'] for q in questions)),category_mapping='Primary metadata labels: unanswerable first, multi-page, structured table, chart/figure, long/localized factual. Long means selected long-source/type bucket; actual PDF lengths also reported. Not all localized factual questions are legal clauses. Original question unchanged.',recall='First production initial-query RRF and Rerank event: chunk ranks mapped to annotated physical pages at K=6 and K=10. Also union recall across Agent searches. No-answer questions have undefined recall, not zero or one.',delivery='EvidenceDelivery with positive content_chars yields actual production-delivered page proxy. Page coverage alone is not exact answer-fragment delivery; grading must check support separately. Visual summary evidence is not OCR/full text.',correctness='Deterministic answer normalization plus one stateless reference/source automatic judge. Raw verdict retained. Same-family model judge not ground truth. Disputed cases separately source-adjudicated; unresolved cases reported as uncertain, not silently passed.',citations='Physical pages extracted from answer and source-checked; extra pages are not automatically wrong solely because gold omits them.',missing='Unavailable downloads, parse/upload/model failures and missing final answers retained; report denominators and unknowns. Previously developed 14 questions are separate regression only.',prohibited='No test-time production tuning. No synthetic questions. No retries for best answer. No gold-page hints in inference. No reference retrieval-base/OCR ground truth injected into Agent.'))
write('regression-exclusion.json',dict(original_questions=14,excluded_source_ids=s['excluded_regression_documents'],excluded_pdf_sha256=sorted(oldsha)))
# Preserve originals/version bytes and implementation identity with the frozen inputs.
for source,target in [('evidence/jit-public-benchmark-20261031/annotations.json','sources/cite-qas.json'),('evidence/jit-public-benchmark-20261031/pdf_source.csv','sources/cite-pdf-source.csv')]: (P/target).write_bytes(pathlib.Path(source).read_bytes())
for n in ['prepare-benchmark100.py','freeze-benchmark100.py','http-benchmark100.cjs']:(P/('runner-'+n)).write_bytes(pathlib.Path('scripts/evaluation/document-jit',n).read_bytes())
files={str(f.relative_to(P)):sha(f.read_bytes()) for f in sorted(P.rglob('*')) if f.is_file() and (f.parent.name in ['pdfs','sources'] or f.name in ['selection.json','downloads.json','frozen-gold.json','inference-manifest.json','production-parameters.json','production-code-before.json','license-audit.json','scoring-protocol.json','regression-exclusion.json','regression-original-14.json'] or f.name.startswith('runner-'))}
lock=dict(frozen_at=datetime.datetime.now(datetime.timezone.utc).isoformat(),model_calls_before_freeze=0,files=files)
write('freeze-lock.json',lock);(P/'freeze-lock.sha256').write_text(sha((P/'freeze-lock.json').read_bytes())+'\n')
print(json.dumps(dict(questions=len(questions),documents=len(docs),splits=collections.Counter(q['split'] for q in questions),invalid_gold_pages=sum(bool(q['invalid_evidence_pages']) for q in questions),lock_sha256=sha((P/'freeze-lock.json').read_bytes()))))
